var PHOTO = "data:image/jpeg;base64,";
  var SISIG_PHOTO = "data:image/jpeg;base64,";
  var CHICHARON_PHOTO = "data:image/jpeg;base64,";
  var LONGGANISA_PHOTO = "data:image/jpeg;base64,";
  var BRINGHE_PHOTO = "data:image/jpeg;base64,";
  var CAMARU_PHOTO = "data:image/jpeg;base64,";
  var DISHES = {
    tupig:{name:'Tupig',origin:'Tarlac original',area:'home',badge:'In Tarlac',badgeBig:'Right here in Tarlac',home:true,photo:PHOTO,
      alt:'Tupig grilled in banana leaves, one unwrapped to show the golden rice cake',
      icon:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M4 9h16M9 4v16"/>',
      desc:'Sticky rice, grated coconut and molasses, wrapped in banana leaf and char-grilled until the edges catch. A merienda classic here.',
      more:'Eat it warm, straight from the leaf, as merienda or alongside coffee.'},
    sisig:{name:'Sisig',origin:'Pampanga, bordering Tarlac',area:'next',badge:'Next door',badgeBig:'Next door in Pampanga',photo:SISIG_PHOTO,
      alt:'Sisig on a cast-iron sizzling plate with calamansi, red chili and red onion',
      icon:'<path d="M4 12h16M4 12c0 4.4 3.6 8 8 8s8-3.6 8-8M4 12c0-1 .3-1.8.8-2.5M20 12c0-1-.3-1.8-.8-2.5M9 4.5c-1 .6-1.6 1.6-1.6 3M15 4.5c1 .6 1.6 1.6 1.6 3"/>',
      desc:'Chopped pork face and liver, seared on a hot plate with calamansi, onions and chili. Loud, sizzling, built for a cold beer.'},
    chicharon:{name:'Chicharon Camiling',origin:'Camiling, Tarlac',area:'home',badge:'Same province',home:true,
      photo:CHICHARON_PHOTO,pos:'center 62%',alt:'Piles of golden, crackling fried pork rind at a market stall',
      icon:'<path d="M6 3c0 4 3 4 3 8s-3 4-3 8M12 3c0 4 3 4 3 8s-3 4-3 8M18 3c0 4 3 4 3 8s-3 4-3 8"/>',
      desc:'Deep-fried pork rind, dried and cooked twice for a crunch that holds up under vinegar dip. Camiling\u2019s name is stamped on every bag sold nearby.'},
    longganisa:{name:'Longganisa',origin:'Local, garlicky style',area:'home',badge:'In Tarlac',home:true,
      photo:LONGGANISA_PHOTO,pos:'center 68%',alt:'Packs of fresh longganisa pork sausage links laid out at a meat stall',
      icon:'<ellipse cx="12" cy="12" rx="8" ry="5"/><path d="M4 12v3c0 2.8 3.6 5 8 5s8-2.2 8-5v-3"/>',
      desc:'Short links of pork sausage, heavy on garlic and a little sweet, fried until the casing snaps. Standard breakfast plate around here.'},
    bringhe:{name:'Bringhe',origin:'Kapampangan glutinous rice',area:'next',badge:'Next door',
      photo:BRINGHE_PHOTO,pos:'center 35%',alt:'Golden turmeric glutinous rice bringhe with chicken and sliced egg on banana leaf',
      icon:'<path d="M4 15c0-5 3.5-9 8-9s8 4 8 9-3.5 4-8 4-8 1-8-4z"/>',
      desc:'The region\u2019s answer to paella: glutinous rice cooked in coconut milk and turmeric, loaded with chicken and chorizo. Fiesta food.'},
    camaru:{name:'Camaru',origin:'Pampanga delicacy',area:'next',badge:'Next door',
      photo:CAMARU_PHOTO,pos:'center 55%',alt:'Fried crickets piled on a banana leaf beside a small bowl of vinegar dip',
      icon:'<path d="M12 3v18M7 7l5-4 5 4M7 17l5 4 5-4"/>',
      desc:'Field crickets, cleaned and fried crisp with garlic and chili. An acquired-taste pulutan that locals swear is mostly crunch and flavor.'}
  };
  var slots = ['tupig','sisig','chicharon','longganisa','bringhe','camaru']; // slots[0] is the spotlight
  var filter = 'all';
  var bento = document.getElementById('bento');
  var dlg = document.getElementById('dish-dialog');

  function svg(path){ return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">'+path+'</svg>'; }

  function render(focusFeature){
    var html = '';
    slots.forEach(function(id, i){
      var d = DISHES[id];
      var hidden = (filter !== 'all' && d.area !== filter) ? ' hidden' : '';
      if(i === 0){
        html += '<article class="card feature'+(d.photo?' has-photo':'')+'" data-area="'+d.area+'" id="spotlight" role="button" tabindex="0" aria-haspopup="dialog" aria-label="'+d.name+'. Open details"'+hidden+'>'
          + (d.photo ? '<img class="photo" src="'+d.photo+'" alt="'+d.alt+'" width="900" height="900" style="object-position:center '+(d.pos?d.pos.replace('center ',''):'40%')+'">' : '<div class="deco"></div>')
          + '<div class="top"><span class="badge">'+(d.badgeBig || d.badge)+'</span></div>'
          + '<div class="origin">'+d.origin+'</div><h3>'+d.name+'</h3><p class="desc">'+d.desc+'</p>'
          + '<span class="more">See more about '+d.name+'</span></article>';
      } else {
        html += '<article class="card" data-area="'+d.area+'" data-slot="'+i+'" role="button" tabindex="0" aria-label="Show '+d.name+' in the spotlight"'+hidden+'>'
          + (d.photo ? '<img class="thumb" src="'+d.photo+'" alt="" width="900" height="675"'+(d.pos?' style="object-position:'+d.pos+'"':'')+'>' : '')
          + '<div class="top"><span class="badge'+(d.home?' home':'')+'">'+d.badge+'</span></div>'
          + '<h3>'+d.name+'</h3><div class="origin">'+d.origin+'</div><p class="desc">'+d.desc+'</p>'
          + '<span class="swap">Show in spotlight</span></article>';
      }
    });
    bento.innerHTML = html;
    if(focusFeature){
      var f = document.getElementById('spotlight');
      f.focus({preventScroll:true});
      f.scrollIntoView({block:'nearest',behavior:'smooth'});
    }
  }

  function activate(e){
    if(e.type === 'keydown' && e.key !== 'Enter' && e.key !== ' '){ return; }
    var card = e.target.closest('.card');
    if(!card){ return; }
    if(e.type === 'keydown'){ e.preventDefault(); }
    if(card.id === 'spotlight'){ openDetails(slots[0]); return; }
    var i = parseInt(card.getAttribute('data-slot'), 10);
    var t = slots[0]; slots[0] = slots[i]; slots[i] = t;   // clicked dish takes the spotlight, the old one takes its place
    render(true);
  }
  bento.addEventListener('click', activate);
  bento.addEventListener('keydown', activate);

  function openDetails(id){
    currentDish = id;
    var d = DISHES[id];
    var img = document.getElementById('dish-dialog-img');
    if(d.photo){ img.src = d.photo; img.alt = d.alt; img.style.objectPosition = d.pos || ''; img.hidden = false; } else { img.hidden = true; }
    document.getElementById('dish-title').textContent = d.name;
    document.getElementById('dish-origin').textContent = d.origin;
    document.getElementById('dish-desc').textContent = d.desc;
    var more = document.getElementById('dish-more');
    more.textContent = d.more || '';
    more.hidden = !d.more;
    dlg.showModal();
  }
  document.getElementById('dish-close').addEventListener('click', function(){ dlg.close(); });
  dlg.addEventListener('click', function(e){ if(e.target === dlg){ dlg.close(); } });

  var chips = document.querySelectorAll('.chip');
  chips.forEach(function(chip){
    chip.addEventListener('click', function(){
      filter = chip.getAttribute('data-filter');
      chips.forEach(function(c){ c.setAttribute('aria-pressed', c === chip ? 'true' : 'false'); });
      render(false);
    });
  });


  /* ===== map ===== */
  var mapFrame = document.getElementById('map-frame');
  var mapOpen = document.getElementById('map-open');
  var mapStatus = document.getElementById('map-status');
  var mapInput = document.getElementById('map-q');
  var currentDish = null;

  function setMap(q, label){
    q = (q || '').trim();
    if(!q){ return; }
    mapFrame.src = 'https://www.google.com/maps?q=' + encodeURIComponent(q) + '&output=embed';
    mapOpen.href = 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(q);
    mapStatus.textContent = 'Showing: ' + (label || q);
  }

  document.getElementById('map-form').addEventListener('submit', function(e){
    e.preventDefault();
    var q = mapInput.value.trim();
    if(q){ setMap(/philippines|tarlac|luzon|manila|cebu|davao|baguio|angeles|pampanga|pangasinan/i.test(q) ? q : q + ' Philippines', q); }
  });

  document.querySelectorAll('.mapchips .chip').forEach(function(chip){
    chip.addEventListener('click', function(){
      setMap(chip.getAttribute('data-q'));
      mapInput.value = '';
    });
  });

  document.getElementById('map-near').addEventListener('click', function(){
    if(!navigator.geolocation){ mapStatus.textContent = 'Your browser can\u2019t share your location.'; return; }
    mapStatus.textContent = 'Finding your location\u2026';
    navigator.geolocation.getCurrentPosition(function(pos){
      setMap('restaurants near ' + pos.coords.latitude + ',' + pos.coords.longitude, 'restaurants near you');
    }, function(){
      mapStatus.textContent = 'Location is blocked. Allow location access, or search by town instead.';
    });
  });

  document.getElementById('dish-map').addEventListener('click', function(){
    var d = DISHES[currentDish];
    dlg.close();
    setMap(d.name + ' near Tarlac City', d.name + ' near Tarlac City');
    document.getElementById('map').scrollIntoView({behavior:'smooth', block:'start'});
  });

  render(false);
